const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeMenindee = ee.Geometry.Polygon([
    [142.2, -32.35],
    [142.5, -32.35],
    [142.5, -32.45],
    [142.2, -32.45],
    [142.2, -32.35]
  ]);

  const date1_start = '2017-01-20';
  const date1_end = '2017-02-03';
  const date2_start = '2019-01-25';
  const date2_end = '2019-02-09';

  // 2. Data Acquisition - Sentinel-2
  function getWaterCollection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(lakeMenindee)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));
  }

  const col1 = getWaterCollection(date1_start, date1_end);
  const col2 = getWaterCollection(date2_start, date2_end);

  // Check if collections are empty
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`2017 Images: ${size1}, 2019 Images: ${size2}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composites for each period
  const img1 = col1.median();
  const img2 = col2.median();

  // Function to calculate water area
  function calculateWaterArea(img) {
    // Calculate NDWI
    const ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Create water mask (NDWI > 0.0 indicates water)
    const waterMask = ndwi.gt(0.0);

    // Count water pixels
    const waterCount = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeMenindee,
      scale: 20,
      maxPixels: 1e9
    }).get('NDWI');

    return waterCount;
  }

  // Calculate water areas
  const waterArea1 = calculateWaterArea(img1);
  const waterArea2 = calculateWaterArea(img2);

  // Get the values
  const area1 = waterArea1.getInfo();
  const area2 = waterArea2.getInfo();

  // Check for no valid pixels
  if (area1 === 0 || area2 === 0) {
    console.log(`Water pixels 2017: ${area1}, 2019: ${area2}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Print results and determine answer
  const shrinkagePercent = ((area1 - area2) / area1 * 100).toFixed(1);
  console.log(`2017 Water pixels: ${area1.toFixed(0)}`);
  console.log(`2019 Water pixels: ${area2.toFixed(0)}`);
  console.log(`Change: ${shrinkagePercent}%`);

  // Determine if lake shrank (threshold: >5% decrease)
  if (area2 < area1 * 0.95) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
